import {validateSnapshot} from './wand.js';
export function pngBlob(snapshot){validateSnapshot(snapshot);const c=typeof OffscreenCanvas==='function'?new OffscreenCanvas(snapshot.width,snapshot.height):Object.assign(document.createElement('canvas'),{width:snapshot.width,height:snapshot.height});c.getContext('2d').putImageData(new ImageData(snapshot.data,snapshot.width,snapshot.height),0,0);if(c.convertToBlob)return c.convertToBlob({type:'image/png'}).finally(()=>{c.width=c.height=1;});return new Promise((resolve,reject)=>c.toBlob(blob=>{c.width=c.height=1;blob?resolve(blob):reject(Error('PNG encoding failed'));},'image/png'));}
// Begin the write in the click/key gesture; resolve the PNG asynchronously inside ClipboardItem.
export function writeImage(snapshot){if(!navigator.clipboard?.write||typeof ClipboardItem!=='function'||!window.isSecureContext)return Promise.reject(Error('Image clipboard is unavailable'));return navigator.clipboard.write([new ClipboardItem({'image/png':pngBlob(snapshot)})]);}
export async function downloadImage(snapshot){const blob=await pngBlob(snapshot),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='UNRULY-selection.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
